using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.Rendering.Universal;using Newtonsoft.Json;
public static class F1WildInspect {
 public static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");public static string Out=>Root+"/Docs/Review/2026-11-13_1F_WildernessDetail/";
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};static float[] C(Color c)=>new[]{c.r,c.g,c.b,c.a};
 public static object Before()=>Run("before");public static object After()=>Run("after");
 static object Run(string phase){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");Directory.CreateDirectory(Out+phase);var ts=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var lights=ts.SelectMany(t=>t.GetComponents<Light>()).Select(l=>new{l.name,path=AnimationUtility.CalculateTransformPath(l.transform,null),type=l.type.ToString(),rotation=V(l.transform.eulerAngles),color=C(l.color),l.intensity,l.enabled,l.useColorTemperature,l.colorTemperature}).ToArray();var sky=ts.SelectMany(t=>t.GetComponents<Skybox>()).Select(c=>new{path=AnimationUtility.CalculateTransformPath(c.transform,null),material=AssetDatabase.GetAssetPath(c.material)}).ToArray();var result=new{scene=s.path,skybox=AssetDatabase.GetAssetPath(RenderSettings.skybox),sun=RenderSettings.sun?RenderSettings.sun.name:null,ambientMode=RenderSettings.ambientMode.ToString(),sky=C(RenderSettings.ambientSkyColor),equator=C(RenderSettings.ambientEquatorColor),ground=C(RenderSettings.ambientGroundColor),RenderSettings.ambientIntensity,RenderSettings.fog,fogMode=RenderSettings.fogMode.ToString(),fogColor=C(RenderSettings.fogColor),RenderSettings.fogDensity,RenderSettings.fogStartDistance,RenderSettings.fogEndDistance,lights,skyOverrides=sky};File.WriteAllText(Out+phase+"_lighting.json",JsonConvert.SerializeObject(result,Formatting.Indented));File.WriteAllText(Out+phase+"_transforms.json",JsonConvert.SerializeObject(ts.Select(t=>new{path=AnimationUtility.CalculateTransformPath(t,null),local=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,c.enabled})}),Formatting.Indented));

 Shot(phase,"Warmup",new Vector3(-66,1.5f,-28),new Vector3(-220,5,-34),76);Shot(phase,"Exit",new Vector3(-51,1.65f,-28),new Vector3(-230,10,-34),76);Shot(phase,"Wilderness",new Vector3(-82,1.65f,-29.1f),new Vector3(-550,25,-46),74);Shot(phase,"Ground",new Vector3(-93,1.6f,-35),new Vector3(-97,.45f,-37),64);Shot(phase,"MidRoute",new Vector3(-285,-.438f,-39.32f),new Vector3(-900,25,-54),74);Shot(phase,"Vista",new Vector3(-590,4.36f,-50.97f),new Vector3(-1900,45,-90),74);Shot(phase,"Factory",new Vector3(-21,2.1f,-10),new Vector3(-12,.7f,2),70);Shot(phase,"Facade",new Vector3(-15,2.4f,-22),new Vector3(-12,3.3f,-14),72);Shot(phase,"Lift",new Vector3(43.2f,1.7f,25.5f),new Vector3(44,1.5f,29),78);
 return new{phase,transforms=ts.Length,sky=result.skybox,sun=result.sun};}
 static void Shot(string phase,string name,Vector3 pos,Vector3 target,float fov){var go=new GameObject("TemporarySunsetCapture"){hideFlags=HideFlags.HideAndDontSave};var c=go.AddComponent<Camera>();c.transform.position=pos;c.transform.LookAt(target);c.fieldOfView=fov;c.nearClipPlane=.04f;c.farClipPlane=8500;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=true;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var active=RenderTexture.active;bool async=ShaderUtil.allowAsyncCompilation;Texture2D tex=null;try{ShaderUtil.allowAsyncCompilation=false;c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(Out+phase+"/"+name+".jpg",tex.EncodeToJPG(94));}finally{RenderTexture.active=active;ShaderUtil.allowAsyncCompilation=async;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
